<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Batch;

use Override;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionCursor;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskContext;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskCounterInterface;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskReaderInterface;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\List\SnippetVersionListUsecase;

class SnippetVersionTaskReader implements TaskReaderInterface, TaskCounterInterface
{
    public function __construct(private readonly SnippetVersionListUsecase $usecase)
    {

    }
    #[Override]
    public function read(TaskContext $context): array
    {
        $filter = $context->params['filter'];
        $cursor = $context->cursor;
        $result = $this->usecase->list($filter, $cursor ?? new SnippetVersionCursor(limit: 1));
        $context->cursor = $result->cursor();
        return $result->values();
    }

    #[Override]
    public function expectedTotal(TaskContext $context): int
    {
        $filter = $context->params['filter'];
        return $this->usecase->count($filter);
    }
}
